window.MOTIF_CATALOG_CHUNKS[62]={"cards":[{"id":"MEJE-KW-003986","row_version":2,"title":"비눗방울을 쏘는 무기","original":"Bubble Gun","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"작품 속 무기가 거품을 발사해 상대를 가두거나 이동을 막는다. 약해 보이는 소재에 다른 규칙을 주어 전투 방식을 바꾼다. 거품을 공격에 쓰는 무기와 몸을 감싸는 거품 방패의 방어 기능이 맞선다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003986/index.html"},{"id":"MEJE-KW-003987","row_version":2,"title":"연기 대신 방울을 내는 파이프","original":"Bubble Pipe","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"담뱃대처럼 생긴 소품에서 비눗방울이 나온다. 어른의 차림을 흉내 내면서도 실제 흡연과는 다른 장면을 만든다. 연기 대신 나오는 방울이 비눗방울 불기로 천진함 표현하기의 장난스러운 분위기를 만들 수 있다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003987/index.html"},{"id":"MEJE-KW-003988","row_version":3,"title":"몸을 감싸는 거품 방패","original":"Bubble Shield","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물의 주위에 거품 같은 막이 생겨 다가오는 공격을 막는다. 잘 터질 듯한 외양과 강한 보호 기능의 차이가 설정의 재미다. 방패가 일시적인 보호를 넘어 생활 공간이 되면 보호용 거품 안에서 살아가는 인물의 설정과 닿는다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-003988/index.html"},{"id":"MEJE-KW-003989","row_version":1,"title":"명랑함으로만 그려진 여성 종업원","original":"Bubbly Waitress","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"여성 종업원이 늘 웃고 손님의 기분을 맞추는 인물로 반복된다. 서비스 노동의 기술과 피로를 성격 하나로 지우지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003989/index.html"},{"id":"MEJE-KW-003990","row_version":1,"title":"허가받지 않은 방송을 하는 인물","original":"Buccaneer Broadcaster","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"제도 밖에서 자신의 목소리를 전파로 보내는 방송인이 등장한다. 들을 권리와 규제의 이유가 사회의 갈등이 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-003990/index.html"},{"id":"MEJE-KW-003991","row_version":1,"title":"문 위에서 양동이가 떨어지는 장난","original":"Bucket Booby-Trap","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"누군가 문을 열 때 위의 양동이가 떨어져 놀라게 하는 장면. 장난의 대상이 겪는 피해와 관계의 분위기에 따라 웃음의 뜻이 달라진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003991/index.html"},{"id":"MEJE-KW-003992","row_version":1,"title":"양동이를 즉석 투구로 쓰기","original":"Bucket Helmet","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 가까운 양동이를 머리에 써 보호 장비나 놀이용 갑옷으로 삼는다. 모양과 실제 보호 기능 사이의 차이가 장면의 웃음이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-003992/index.html"},{"id":"MEJE-KW-003993","row_version":1,"title":"죽기 전에 해보고 싶은 일의 목록","original":"Bucket List","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 남은 시간을 의식하며 아직 하지 못한 일을 적는다. 항목을 지우는 과정에서 무엇이 자신에게 중요한지 다시 고른다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-003993/index.html"},{"id":"MEJE-KW-003994","row_version":2,"title":"성격 다른 두 수사관이 이끄는 범죄극","original":"Buddy Cop Show","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"두 수사관이 서로 다른 방식으로 사건을 풀며 동료가 된다. 수사와 관계의 변화가 나란히 진행되는 장르 형식이다. 수사라는 직업적 목표를 덜어내면 두 친구가 주인공인 동행 이야기의 동행 구조가 더 뚜렷해진다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003994/index.html"},{"id":"MEJE-KW-003995","row_version":1,"title":"두 친구가 주인공인 동행 이야기","original":"Buddy Picture","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"성격이나 처지가 다른 두 친구가 같은 여정을 겪는다. 서로를 이해하고 협력하는 과정이 사건만큼 중요하다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-003995/index.html"},{"id":"MEJE-KW-003996","row_version":3,"title":"참던 동료가 먼저 화내기","original":"Buddy Snaps First","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"주인공이 화를 내기 직전 더 차분하던 동료가 먼저 행동한다. 평소 역할이 바뀌며 둘이 겪은 불만의 크기가 드러난다. 두 주인공의 관계를 이끄는 두 친구가 주인공인 동행 이야기에서 참던 동료의 반응이 전환점이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003996/index.html"},{"id":"MEJE-KW-003997","row_version":1,"title":"제작비를 크게 쓰게 하는 한 요소","original":"Budget-Busting Element","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"세트나 인물, 시각효과 하나가 작품의 비용을 크게 늘린다. 화면에 보이는 짧은 순간과 그것을 만드는 자원의 차이가 생긴다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-003997/index.html"},{"id":"MEJE-KW-003998","row_version":1,"title":"뷔페에서 지나치게 많이 담는 소동","original":"Buffet Buffoonery","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"사람들이 정해진 값으로 최대한 많이 먹으려다 음식과 욕심을 둘러싼 소동을 만든다. 낭비와 장난을 누가 감당하는지도 장면의 일부다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-003998/index.html"},{"id":"MEJE-KW-003999","row_version":1,"title":"허술하게 구는 수고양이","original":"Buffoonish Tomcat","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"수고양이가 늘 민첩하고 영리하리라는 예상과 달리 실수와 허세로 웃음을 만든다. 성별을 성격의 이유로 삼는 동물 관습과 구분한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-003999/index.html"},{"id":"MEJE-KW-004000","row_version":1,"title":"모르는 말을 임시 단어로 바꾸는 말투","original":"Buffy Speak","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 정확한 명칭 대신 즉석에서 만든 말과 어색한 문장으로 뜻을 전한다. 재치와 막힘이 함께 보이는 대사의 리듬이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-004000/index.html"},{"id":"MEJE-KW-004001","row_version":2,"title":"벌레의 윙윙거림으로 불편함 만들기","original":"Bug Buzz","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"날아다니는 벌레의 반복적인 소리가 인물의 집중을 흐리고 공간을 답답하게 만든다. 작은 생물을 보이지 않게 두어도 소리만으로 존재를 알린다. 곤충의 소리가 불길한 사건의 예고가 되면 곤충 떼로 더 큰 악을 예고하기의 징조로 발전한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-004001/index.html"},{"id":"MEJE-KW-004002","row_version":1,"title":"여름에 곤충을 잡아 관찰하기","original":"Bug Catching","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 작은 곤충을 찾아 잡고 가까이서 관찰한다. 호기심과 돌봄의 태도에 따라 놀이의 의미가 달라진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004002/index.html"},{"id":"MEJE-KW-004003","row_version":2,"title":"곤충 떼로 더 큰 악을 예고하기","original":"Bugs Herald Evil","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"벌레들이 갑자기 모이거나 흩어지는 모습이 다른 위협의 도래를 알린다. 곤충 자체의 선악보다 장면이 부여한 징조가 중요하다. 벌레의 이미지를 적대 종족 전체로 넓히면 사람과 곤충형 종족의 전쟁의 갈등이 된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-004003/index.html"},{"id":"MEJE-KW-004004","row_version":1,"title":"사람과 곤충형 종족의 전쟁","original":"Bug War","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인간 사회가 곤충처럼 생긴 다른 종족과 큰 전쟁을 벌인다. 낯선 몸을 곧바로 적의 도덕성으로 읽는 설정인지도 살핀다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-004004/index.html"},{"id":"MEJE-KW-004005","row_version":1,"title":"작업 장면을 용접 불꽃으로 대표하기","original":"Building Is Welding","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"건물을 만들거나 고치는 과정을 짧은 용접 장면으로 보여 준다. 불꽃이 노동의 크기를 전하지만 실제 작업 전체를 뜻하지는 않는다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004005/index.html"},{"id":"MEJE-KW-004006","row_version":1,"title":"건물을 지을 수 있는 위치의 게임 규칙","original":"Building Location Restrictions","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"전략 게임이 특정 땅이나 시설 근처에만 새 건물을 놓게 한다. 제한된 자리가 기지의 성장과 방어 계획을 바꾼다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-004006/index.html"},{"id":"MEJE-KW-004007","row_version":2,"title":"한 건물 안에서 모험이 모두 벌어지기","original":"Building of Adventure","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"복잡한 건물 하나가 탐색과 갈등, 뜻밖의 만남을 모두 품는다. 방과 층의 연결이 여정의 지도 역할을 한다. 모험이 한 건물에 모여도 건물 사이를 매달려 이동하기를 통해 건물 밖으로 이동할 수 있다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-004007/index.html"},{"id":"MEJE-KW-004008","row_version":1,"title":"건물 사이를 매달려 이동하기","original":"Building Swing","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 높은 건물의 구조물을 붙잡고 흔들리며 다음 장소로 간다. 이동 경로가 도시의 높이와 속도를 보여 준다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004008/index.html"},{"id":"MEJE-KW-004009","row_version":1,"title":"피라미드로 이집트풍 세계를 나타내기","original":"Build Like an Egyptian","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 피라미드와 오벨리스크를 놓아 고대 이집트를 닮은 세계라고 알린다. 몇 가지 건축 기호로 다양한 역사와 문화를 줄이는 관습도 드러난다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-004009/index.html"},{"id":"MEJE-KW-004010","row_version":1,"title":"조립 블록으로 만든 듯한 세계","original":"Built with LEGO","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"사물과 인물이 작은 조립 블록의 형태로 표현되고 분해·재조립된다. 재료의 공통 규칙이 건축과 움직임의 분위기를 만든다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004010/index.html"},{"id":"MEJE-KW-004011","row_version":1,"title":"필요한 물건을 묶음으로만 사기","original":"Bulk-Buy Only","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"작은 물건 하나가 필요하지만 판매자가 지나치게 큰 묶음만 내놓는다. 필요한 양과 떠안은 양의 차이가 이후 소동을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004011/index.html"},{"id":"MEJE-KW-004012","row_version":2,"title":"날아오는 총알을 손으로 붙잡기","original":"Bullet Catch","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 보통은 피해야 할 작은 발사체를 손으로 받아 힘의 차이를 보인다. 이 행동은 실제 가능성보다 초월적 반응 속도의 표지다. 날아온 총알을 잡는 힘과 총알이 인물을 비껴가기처럼 총알이 스스로 방향을 바꾸는 힘은 다르다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-004012/index.html"},{"id":"MEJE-KW-004013","row_version":1,"title":"발치에 쏜 총탄을 피해 춤추듯 뛰기","original":"Bullet Dancing","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"위협받는 사람이 발치의 총격을 피하느라 연달아 뛰어오른다. 장면은 굴욕이나 공포로 읽히며 장난처럼 보이게 해도 폭력의 책임은 남는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004013/index.html"},{"id":"MEJE-KW-004014","row_version":1,"title":"총알이 인물을 비껴가기","original":"Bullet Dodges You","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물은 거의 움직이지 않는데 발사체가 스스로 경로를 바꿔 그를 피한다. 능력의 원인과 적용 범위가 위험의 규칙을 바꾼다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-004014/index.html"},{"id":"MEJE-KW-004015","row_version":1,"title":"발사체가 화면을 가득 채우는 슈팅 게임","original":"Bullet Hell","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"수많은 발사체의 무늬 사이에서 좁은 길을 찾아 움직이는 슈팅 게임의 유형. 피하는 동선과 반복 학습이 진행의 중심이다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-004015/index.html"},{"id":"MEJE-KW-004016","row_version":2,"title":"총탄으로 벽에 출구를 내기","original":"Bullethole Door","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"작품이 여러 발의 총격으로 벽이나 바닥을 무너뜨려 통로를 만든다. 물리적 결과를 극적으로 단순화한 탈출 장면이다. 총탄이 벽에 남긴 자국을 뜻있는 형태로 배열하면 총탄 자국으로 글씨 남기기의 메시지가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004016/index.html"},{"id":"MEJE-KW-004017","row_version":1,"title":"총성이 난 뒤 누가 맞았는지 늦게 밝히기","original":"Bullet Holes and Revelations","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"두 인물이 실랑이하다 총성이 나지만 화면은 곧바로 피해자를 보여 주지 않는다. 짧은 지연이 관객의 예상을 흔든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-004017/index.html"},{"id":"MEJE-KW-004018","row_version":1,"title":"총탄 자국으로 글씨 남기기","original":"Bullet Hole Spelling","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"벽에 남은 탄흔을 글자나 표식처럼 배열해 누군가의 메시지를 전한다. 상처 입은 공간이 위협의 기록이 된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004018/index.html"},{"id":"MEJE-KW-004019","row_version":1,"title":"재난 속에서도 흐트러지지 않는 옷차림","original":"Bullet-Proof Fashion Plate","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"큰 충돌과 먼지를 겪은 인물의 옷과 머리가 처음처럼 단정하다. 인물의 우아함이나 매체의 생략이 현실적 결과보다 앞선다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004019/index.html"},{"id":"MEJE-KW-004020","row_version":2,"title":"사람을 총알막이로 쓰기","original":"Bulletproof Human Shield","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 다른 사람의 몸을 앞에 세워 자신에게 향한 총격을 피한다. 위험을 떠넘기는 행위와 그 사람의 피해가 장면의 중심이다. 몸을 방패로 삼는 행위는 사람이 입을 수 있는 탄환을 막는 보호 조끼와 달리 다른 이에게 피해를 떠넘긴다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004020/index.html"},{"id":"MEJE-KW-004021","row_version":1,"title":"탄환을 막는 보호 조끼","original":"Bulletproof Vest","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 총격의 위험을 줄이려고 방호용 조끼를 입는다. 작품 안에서 무엇을 막고 무엇을 막지 못하는지가 긴장을 만든다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-004021/index.html"},{"id":"MEJE-KW-004022","row_version":1,"title":"씨앗을 연속 발사하기","original":"Bullet Seed","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이나 생물이 작은 씨앗을 빠르게 뿜어 상대를 압박한다. 평범한 식물의 일부가 작품 속 공격 능력으로 바뀐다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-004022/index.html"},{"id":"MEJE-KW-004023","row_version":1,"title":"총탄이 닿은 곳에서 튀는 불꽃","original":"Bullet Sparks","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"발사체가 벽과 금속에 부딪힐 때 밝은 불꽃이 튄다. 어디에 맞았는지를 관객에게 곧바로 알리는 화면의 관습이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004023/index.html"},{"id":"MEJE-KW-004024","row_version":2,"title":"격투 순간 시간이 느려 보이기","original":"Bullet Time","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"격한 행동 중 짧은 순간을 천천히 보여 주어 몸과 발사체의 경로를 또렷하게 만든다. 관객이 보지 못했을 세부를 장면의 중심으로 끌어온다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-004024/index.html"},{"id":"MEJE-KW-004025","row_version":2,"title":"돌진한 보스가 스스로 빈틈을 만들기","original":"Bullfight Boss","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"보스가 반복해서 돌진하고 플레이어는 피한 뒤 잠깐 드러난 틈에 대응한다. 적의 힘을 이용해 반격할 시간을 만드는 전투 규칙이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-004025/index.html"},{"id":"MEJE-KW-004026","row_version":2,"title":"괴롭힘 뒤에 우울해진 인물","original":"Bullied into Depression","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"반복되는 괴롭힘이 인물의 기분과 일상을 오래 흔든다. 개인의 약함이 아니라 가해와 방치의 결과로 관계를 다룬다. 우울의 배경에 큰 상해를 가하는 괴롭힘처럼 큰 상해를 주는 가해가 있을 수도 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-004026/index.html"},{"id":"MEJE-KW-004027","row_version":2,"title":"붉은색만 보면 돌진하는 수소라는 속설","original":"Bull Seeing Red","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 수소가 빨간 옷을 보자마자 화를 내고 쫓아온다고 묘사한다. 색 자체보다 장면의 움직임과 동물에 붙인 성격이 만든 허구 관습이다. 붉은색에 반응한다는 이야기는 수소를 난폭한 동물로만 그리기의 단순한 동물 이미지와 함께 쓰인다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-004027/index.html"},{"id":"MEJE-KW-004028","row_version":2,"title":"괴롭히던 사람과 피해자를 억지로 한 팀에 넣기","original":"Bully and Wimp Pairing","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"서로를 두려워하거나 미워하던 두 인물이 같은 목표를 수행해야 한다. 피해자의 안전과 가해자의 책임이 협력보다 먼저 다뤄져야 한다. 억지 협력이 신뢰로 바뀌려면 괴롭히던 사람이 친구가 되기처럼 가해자의 행동 변화가 필요하다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-004028/index.html"},{"id":"MEJE-KW-004029","row_version":2,"title":"큰 상해를 가하는 괴롭힘","original":"Bully Brutality","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가해자가 가벼운 놀림을 넘어서 상대의 몸과 생명을 위협한다. 심각성을 장난의 크기 차이로 줄이지 않고 폭력의 책임을 드러낸다. 상대의 힘을 모른 채 시작한 괴롭힘도 강한 상대인 줄 모르고 괴롭히기의 반전으로 정당화되지는 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004029/index.html"},{"id":"MEJE-KW-004030","row_version":1,"title":"불량배로 그려진 불도그","original":"Bully Bulldog","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 불도그의 외모를 근거로 거칠고 위협적인 동물 인물로 만든다. 품종의 모습과 행동의 도덕성을 잇는 고정관념이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-004030/index.html"},{"id":"MEJE-KW-004031","row_version":1,"title":"괴롭힘을 막으러 나서는 인물","original":"Bully Hunter","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"남을 괴롭히는 사람을 찾아가 피해자를 돕는 인물이 등장한다. 도움의 방식이 또 다른 폭력이나 통제로 이어지지 않는지도 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-004031/index.html"},{"id":"MEJE-KW-004032","row_version":2,"title":"강한 상대인 줄 모르고 괴롭히기","original":"Bullying a Dragon","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가해자가 힘없는 사람이라 여기고 괴롭힌 상대가 자신보다 훨씬 강하다는 사실을 알게 된다. 반전의 즐거움과 원래의 가해 책임은 별개다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004032/index.html"},{"id":"MEJE-KW-004033","row_version":2,"title":"안경을 이유로 괴롭히기","original":"Bullying the Bespectacled","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가해자가 안경을 쓴 사람의 외모나 시력을 조롱한다. 장난처럼 보이는 말이 일상의 안전을 해칠 수 있다. 외모나 몸의 차이를 골라 조롱한다는 점에서 장애를 이유로 괴롭히기의 차별과 함께 살핀다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004033/index.html"},{"id":"MEJE-KW-004034","row_version":2,"title":"장애를 이유로 괴롭히기","original":"Bullying the Disabled","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가해자가 상대의 장애를 골라 놀리거나 배제한다. 장애 자체보다 차별적 행동과 주변의 대응이 사건의 문제다. 한 사람을 계속 표적으로 삼는 계속 괴롭힘의 대상이 되는 인물의 구도에 장애를 이유로 한 차별이 더해질 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004034/index.html"},{"id":"MEJE-KW-004035","row_version":2,"title":"계속 괴롭힘의 대상이 되는 인물","original":"Bully Magnet","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"한 인물이 여러 가해자에게 반복해서 괴롭힘을 당하는 역할로 놓인다. 옷차림이나 성격을 원인으로 돌리지 않고 가해와 방치의 구조를 본다. 반복된 가해의 영향은 괴롭힘 뒤에 우울해진 인물의 감정과 일상에도 나타난다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-004035/index.html"},{"id":"MEJE-KW-004036","row_version":3,"title":"괴롭히던 사람이 친구가 되기","original":"Bully Turned Buddy","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"과거의 가해자가 행동을 바꾸고 피해자와 새 관계를 맺는다. 화해가 성립하려면 책임 인정과 피해자의 선택이 필요하다. 과거의 가해자와 피해자가 한편이 되는 괴롭히던 사람과 피해자를 억지로 한 팀에 넣기보다 책임을 인정한 뒤의 선택이 중심이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-004036/index.html"},{"id":"MEJE-KW-004037","row_version":3,"title":"아프리카 국가를 하나의 전형으로 그리기","original":"Bulungi","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 여러 아프리카 사회를 한 가상국의 정글과 사바나, 단순한 정치로 뭉뚱그린다. 실제 지역의 차이와 생활을 지우는 세계관의 관습이다. 지역 문화를 몇 가지 건축 기호로 줄이는 피라미드로 이집트풍 세계를 나타내기와 함께 세계관의 전형화를 살펴볼 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-004037/index.html"},{"id":"MEJE-KW-004038","row_version":1,"title":"주장의 내용 대신 말한 사람의 동기만 공격하기","original":"Bulverism","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 상대의 논거를 검토하기 전에 왜 그 말을 믿고 싶어 하는지 추측해 반박한다. 동기에 대한 설명만으로 주장의 참과 거짓은 정해지지 않는다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-004038/index.html"},{"id":"MEJE-KW-004039","row_version":1,"title":"실수투성이 아버지라는 가족 인물 틀","original":"Bumbling Dad","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"아버지가 집안일과 돌봄에 늘 서툰 사람으로 그려진다. 웃음의 기능이 부모의 책임과 능력을 성별로 고정할 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-004039/index.html"},{"id":"MEJE-KW-004040","row_version":2,"title":"실수로 계획을 망치는 악역 부하 둘","original":"Bumbling Henchmen Duo","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"같은 악역 밑에서 일하는 두 부하가 서로의 실수를 키우며 임무를 어긋나게 한다. 상사의 위협과 두 사람의 우정이 다른 분위기를 만든다. 두 사람이 함께 실수하는 관계는 한 명의 도움을 주려다 일을 망치는 동료를 두는 구성과 다르다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-004040/index.html"},{"id":"MEJE-KW-004041","row_version":2,"title":"도움을 주려다 일을 망치는 동료","original":"Bumbling Sidekick","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"주인공 곁의 조력자가 선의를 갖고도 반복해서 실수한다. 관계가 유지되는 이유가 실력 말고 무엇인지 살필 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-004041/index.html"},{"id":"MEJE-KW-004042","row_version":1,"title":"차에 붙인 짧은 문구의 스티커","original":"Bumper Sticker","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"차량의 바깥에 작은 문구나 그림을 붙여 소유자의 생각과 취향을 보여 준다. 이동하는 사물이 공개된 자기소개가 된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-004042/index.html"},{"id":"MEJE-KW-004043","row_version":1,"title":"가벼운 몸의 충돌이 다툼으로 번지기","original":"Bump into Confrontation","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"길에서 우연히 부딪힌 사람이 과하게 반응해 시비를 건다. 사소한 접촉이 권력과 감정의 충돌로 커진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004043/index.html"},{"id":"MEJE-KW-004044","row_version":1,"title":"최면이 엉뚱한 사람이나 행동으로 빗나가기","original":"Bungled Hypnotism","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"작품 속 최면이 예상과 다른 대상에게 걸리거나 의도치 않은 행동을 낳는다. 통제한다고 믿은 인물이 결과를 다루지 못하는 허구의 역전이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-004044/index.html"},{"id":"MEJE-KW-004045","row_version":1,"title":"죽으려 했지만 살아남은 인물","original":"Bungled Suicide","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이 죽음을 시도한 뒤 살아남아 몸과 관계의 변화를 마주한다. 구체적인 방식보다 위기 이후의 안전과 도움, 회복의 선택을 중심에 둔다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-004045/index.html"},{"id":"MEJE-KW-004046","row_version":1,"title":"늘 예상 밖으로 고장 나는 발명가의 작품","original":"Bungling Inventor","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"발명가가 만든 장치가 의도한 기능과 다른 결과를 낳는다. 실패의 반복이 새 문제를 만들거나 뜻밖의 해결책이 될 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-004046/index.html"},{"id":"MEJE-KW-004047","row_version":1,"title":"지하 공간에 감금된 여성","original":"Bunker Woman","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"여성이 의사에 반해 지하의 닫힌 공간에 갇힌다. 출구를 찾는 일뿐 아니라 감금한 사람이 통제하는 정보와 시간을 견디는 일이 갈등이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004047/index.html"},{"id":"MEJE-KW-004048","row_version":1,"title":"토끼로 귀여움을 표현하기","original":"Bunnies for Cuteness","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"토끼나 토끼 모양 물건을 인물 곁에 두어 부드럽고 어린 인상을 만든다. 동물이 지닌 뜻은 인물의 실제 성격과 다를 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004048/index.html"},{"id":"MEJE-KW-004049","row_version":1,"title":"기행이 있어도 실력으로 인정받는 전문가","original":"Bunny-Ears Lawyer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"특이한 행동 때문에 함께 일하기 어렵지만 능력이 뛰어나 조직에 남는 인물. 주위의 인내가 어디까지 가능한지도 관계의 일부다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-004049/index.html"},{"id":"MEJE-KW-004050","row_version":1,"title":"단체 사진 뒤에서 손가락으로 장난치기","original":"Bunny Ears Picture Prank","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"사진을 찍는 순간 다른 사람의 머리 뒤에 손가락을 올려 모양을 만든다. 문화와 관계에 따라 장난의 의미가 다르게 받아들여질 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004050/index.html"},{"id":"MEJE-KW-004051","row_version":1,"title":"떠맡은 일을 한꺼번에 원망하기","original":"Burden Rant","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"오래도록 가족이나 동료의 몫까지 감당한 인물이 쌓인 피로를 말로 쏟아낸다. 당장의 분노 뒤에 불균형한 책임이 보인다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-004051/index.html"},{"id":"MEJE-KW-004052","row_version":2,"title":"관청 업무를 중심으로 한 게임","original":"Bureaucracy Simulator","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"플레이어가 서류와 규칙, 민원 사이에서 판단하는 역할을 맡는 게임 유형. 작은 결정이 제도와 사람의 삶을 연결한다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-004052/index.html"},{"id":"MEJE-KW-004053","row_version":1,"title":"행정 절차가 정하는 결혼","original":"Bureaucratically Arranged Marriage","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"공적 기관이 적합성을 계산하거나 명령해 두 사람의 혼인을 정한다. 사회의 기준과 당사자의 동의가 충돌한다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-004053/index.html"},{"id":"MEJE-KW-004054","row_version":1,"title":"패스트푸드점의 지친 직원","original":"Burger Fool","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"반복되는 주문과 낮은 자율성 속에서 일하는 직원이 이야기의 주변 인물로 등장한다. 짧은 응대에도 노동의 조건과 성격이 드러날 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-004054/index.html"},{"id":"MEJE-KW-004055","row_version":2,"title":"바다에서 치르는 장례","original":"Burial at Sea","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"죽은 이를 배에서 보내거나 유해를 바다에 돌려보내는 의례. 항해하는 사람들에게 바다가 삶의 장소이자 마지막 장소가 된다. 바다를 떠나보내는 장소로 삼는 의례는 우주에서 치르는 장례에서 우주 공간으로 바뀐다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-004055/index.html"},{"id":"MEJE-KW-004056","row_version":3,"title":"우주에서 치르는 장례","original":"Burial in Space","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"우주선의 승무원이 죽은 동료를 별들 사이로 떠나보낸다. 닫힌 선내와 광대한 바깥 공간의 대비가 이별을 크게 만든다. 닫힌 배 안에서 동료를 보내는 모습은 바다에서 치르는 장례와 닮은 공간의 이별이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-004056/index.html"},{"id":"MEJE-KW-004057","row_version":1,"title":"산 채로 땅에 묻히기","original":"Buried Alive","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 살아 있는 채 땅속에 갇혀 밖의 도움이나 탈출을 기다린다. 시간과 고립이 위협의 핵심이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004057/index.html"},{"id":"MEJE-KW-004058","row_version":1,"title":"시신들 사이에 숨어 살아남기","original":"Buried in a Pile of Corpses","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 발견되지 않으려고 죽은 사람들 사이에 몸을 감춘다. 살아남았다는 사실과 그 자리에서 본 일이 이후의 상처로 남을 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004058/index.html"},{"id":"MEJE-KW-004059","row_version":1,"title":"벌레스크 공연","original":"Burlesque","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"풍자와 과장된 몸짓, 음악을 섞어 관객에게 보여 주는 무대 공연 유형. 시대와 작품에 따라 조롱과 관능의 비중이 달라진다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-004059/index.html"},{"id":"MEJE-KW-004060","row_version":2,"title":"크고 다정한 대장장이","original":"Burly Blacksmith","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"강한 팔과 큰 체격으로 무기를 만들지만 사람을 대할 때는 조심스럽고 다정한 인물. 노동에서 얻은 힘과 관계의 태도를 함께 보여 준다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-004060/index.html"},{"id":"MEJE-KW-004061","row_version":1,"title":"이름 대신 화려한 수식어를 반복하기","original":"\"Burly Detective\" Syndrome","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"글이 같은 인물을 부를 때마다 이름을 피하고 외모나 직업을 길게 묘사한다. 반복을 피하려는 시도가 오히려 문장을 복잡하게 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-004061/index.html"},{"id":"MEJE-KW-004062","row_version":2,"title":"중요한 물건을 불태워 결별하기","original":"Burn Baby Burn","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 서류나 기념품을 불에 넣어 과거와 관계를 끊겠다고 표시한다. 사라지는 물건과 남는 기억 사이에 차이가 있다. 개인 물건 대신 사람을 나타낸 모형을 태우면 인물을 본뜬 상을 태우기의 공개적 뜻이 더해진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004062/index.html"},{"id":"MEJE-KW-004063","row_version":1,"title":"쓰고 버리는 연락용 전화","original":"Burner Phones","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 짧은 기간만 쓰는 전화로 연락해 자신의 행적을 숨기려 한다. 도구의 교체가 서로를 믿지 못하는 관계를 보여 준다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-004063/index.html"},{"id":"MEJE-KW-004064","row_version":2,"title":"인물을 본뜬 상을 태우기","original":"Burning an Effigy","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"한 사람이나 생각을 나타내는 모형을 불태워 공개적인 분노 또는 의례적 작별을 표현한다. 불을 보는 집단이 무엇에 동의하는지가 중요하다. 공개적인 불로 상징을 해친다는 점에서는 깃발을 태우는 항의와 닮았다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-004064/index.html"},{"id":"MEJE-KW-004065","row_version":1,"title":"불붙은 물건으로 집 앞 장난치기","original":"Burning Bag of Poop","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 남의 집 앞에 위험하고 불쾌한 물건을 남겨 당황을 노린다. 장난이라는 이름이 실제 피해와 화재 위험을 지우지 않는다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-004065/index.html"},{"id":"MEJE-KW-004066","row_version":1,"title":"불꽃으로 여는 첫 장면","original":"Burning Beginning","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"작은 불빛이나 큰 화재를 첫 화면에 두어 이야기의 분위기를 정한다. 불의 크기와 쓰임이 시작의 희망 또는 위기를 예고한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004066/index.html"},{"id":"MEJE-KW-004067","row_version":1,"title":"빠른 움직임 뒤에 남는 불길","original":"Burning Rubber","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"달리는 인물이나 차량 뒤에 과장된 불꽃 자국을 그린다. 실제 마찰의 결과보다 속도의 인상을 시각화하는 기호다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004067/index.html"},{"id":"MEJE-KW-004068","row_version":1,"title":"깃발을 태우는 항의","original":"Burning the Flag","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 집단을 나타내는 깃발에 불을 붙여 적대나 항의의 뜻을 공개한다. 상징을 해치는 행동과 사람들이 받는 모욕감이 함께 드러난다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004068/index.html"},{"id":"MEJE-KW-004069","row_version":1,"title":"돌아갈 길을 스스로 없애기","original":"Burning the Ships","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 뒤로 물러날 수단을 없애 앞으로 나아가도록 자신과 동료를 몰아간다. 결의의 표시인 동시에 다른 사람의 선택권을 빼앗을 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-004069/index.html"},{"id":"MEJE-KW-004070","row_version":2,"title":"분노를 불꽃으로 그리기","original":"Burning with Anger","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물이 격분할 때 몸의 주변에 불이나 열기를 그려 감정의 크기를 보여 준다. 실제 불을 다루는 능력인지 시각적 비유인지는 작품의 규칙에 달렸다. 불꽃이 시각적 비유를 넘어 실제 힘이라면 그 사용의 대가가 불을 다루는 인물의 화상 흔적으로 남을 수 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004070/index.html"},{"id":"MEJE-KW-004071","row_version":1,"title":"힘든 직무에 지쳐 떠나는 인물","original":"Burnout by Traumatic Job","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"반복해서 위험과 고통을 마주한 인물이 더는 일을 이어 갈 수 없다고 느낀다. 그 사람의 성격만이 아니라 일을 떠받치는 조직도 살핀다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-004071/index.html"},{"id":"MEJE-KW-004072","row_version":1,"title":"불을 다루는 인물의 화상 흔적","original":"Burn Scars, Burning Powers","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"불을 쓰는 힘을 지닌 인물의 몸에 화상의 흔적이 남아 있다. 힘을 얻은 일과 몸에 남은 경험이 함께 인물을 설명한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-004072/index.html"},{"id":"MEJE-KW-004073","row_version":2,"title":"보호받아야 할 시설을 불태우는 악역","original":"Burn the Orphanage","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"악역이 아이들이 머무는 곳처럼 보호가 필요한 시설을 해쳐 잔혹함을 드러낸다. 피해자의 삶을 악역의 점수처럼 쓰지 않는 재현이 필요하다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-004073/index.html"},{"id":"MEJE-KW-004074","row_version":1,"title":"불에 약한 언데드","original":"Burn the Undead","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"다른 공격에는 버티는 죽지 않는 존재가 불 앞에서는 약해진다. 어떤 불이 통하고 왜 그런지가 세계의 규칙을 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-004074/index.html"},{"id":"MEJE-KW-004075","row_version":2,"title":"마녀로 몰린 사람을 불태우려는 군중","original":"Burn the Witch!","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"공동체가 불행의 원인을 한 사람에게 돌리고 처벌을 요구한다. 실제 힘의 유무보다 두려움과 비난이 모이는 과정이 중심이다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-004075/index.html"},{"id":"MEJE-KW-004076","row_version":1,"title":"트림 소리로 겨루기","original":"Burping Contest","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물들이 트림의 크기나 길이를 놓고 가벼운 경쟁을 한다. 사소한 몸의 소리가 체면과 장난의 문제가 된다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-004076/index.html"},{"id":"MEJE-KW-004077","row_version":1,"title":"포식이 끝났음을 알리는 트림","original":"Burp of Finality","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"생물이 무언가를 삼킨 뒤 트림하여 보이지 않은 일을 짧게 알린다. 자세한 폭력을 보여 주지 않고도 결과를 짐작하게 한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004077/index.html"},{"id":"MEJE-KW-004078","row_version":2,"title":"유해 없이 치르는 장례","original":"Burying a Substitute","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"시신을 찾지 못한 사람들이 물건이나 빈 관을 놓고 장례를 치른다. 몸이 없어도 작별의 자리와 기억은 필요하다. 몸을 찾지 못하면 원하는 곳에 묻어 달라는 마지막 부탁를 지키는 방법도 달라진다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-004078/index.html"},{"id":"MEJE-KW-004079","row_version":1,"title":"원하는 곳에 묻어 달라는 마지막 부탁","original":"Bury Me Not on the Lone Prairie","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"죽음을 앞둔 인물이 유해를 둘 장소를 부탁하고 남은 사람이 그 약속을 지키려 한다. 길의 어려움이 관계의 책임을 보여 준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-004079/index.html"},{"id":"MEJE-KW-004080","row_version":1,"title":"만든 작품을 스스로 감추기","original":"Bury Your Art","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"창작자나 권리자가 이미 만든 작품을 사람들이 보지 못하게 막는다. 공개하지 않으려는 이유와 작품을 기다린 사람의 입장이 충돌한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-004080/index.html"},{"id":"MEJE-KW-004081","row_version":3,"title":"장애인 인물의 죽음을 서사 도구로 쓰기","original":"Bury Your Disabled","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 장애가 있는 인물을 죽게 하여 다른 인물의 변화만 강조한다. 죽은 인물에게 독립적인 삶과 선택이 있었는지 살핀다. 인물의 정체성을 죽음의 장치로만 쓰는 재현 문제는 성소수자 인물의 죽음을 서사 도구로 쓰기에서도 살핀다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-004081/index.html"},{"id":"MEJE-KW-004082","row_version":2,"title":"성소수자 인물의 죽음을 서사 도구로 쓰기","original":"Bury Your Gays","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 성소수자 인물의 죽음으로 다른 인물의 슬픔이나 성장을 이끈다. 당사자의 삶이 충분히 그려졌는지와 죽음 이후 남는 관계를 살핀다. 죽은 당사자의 삶보다 남의 변화만 앞세우는 문제는 장애인 인물의 죽음을 서사 도구로 쓰기와도 이어진다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-004082/index.html"},{"id":"MEJE-KW-004083","row_version":2,"title":"기하학적 군무를 위에서 보여 주기","original":"Busby Berkeley Number","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"많은 무용수가 규칙적인 대형을 만들고 카메라가 전체 모양을 잡는다. 개인의 춤과 집단의 무늬가 동시에 공연이 된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-004083/index.html"},{"id":"MEJE-KW-004084","row_version":1,"title":"떠난 조연을 돌아오기 전에 죽이기","original":"Bus Crash","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"이야기에서 잠시 빠졌던 인물이 다시 등장할 듯하다가 바깥에서 죽은 것으로 처리된다. 돌아오리라는 기대를 깨는 제작 선택이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-004084/index.html"},{"id":"MEJE-KW-004085","row_version":2,"title":"대중교통 이용자를 기이하게 그리기","original":"Buses Are for Freaks","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"버스나 기차를 탄 사람들을 가난하거나 이상한 인물로만 꾸민다. 이동 수단을 사회적 지위와 성격의 증거로 삼는 관습을 살핀다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-004085/index.html"}]}.cards;